CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS market_news (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), source VARCHAR(160) NOT NULL, source_url TEXT, headline TEXT NOT NULL, published_at TIMESTAMPTZ, fetched_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP, content_hash CHAR(64) UNIQUE, raw_text TEXT, status VARCHAR(32) NOT NULL DEFAULT 'INGESTED');
CREATE TABLE IF NOT EXISTS news_analysis (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), news_id UUID NOT NULL REFERENCES market_news(id), provider VARCHAR(40) NOT NULL, model VARCHAR(100), sentiment VARCHAR(24) NOT NULL DEFAULT 'NEUTRAL', affected_symbols JSONB NOT NULL DEFAULT '[]'::jsonb, summary TEXT, risks JSONB NOT NULL DEFAULT '[]'::jsonb, analyzed_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS trade_signal (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), symbol VARCHAR(20) NOT NULL, action VARCHAR(20) NOT NULL, strategy VARCHAR(100) NOT NULL, reference_price NUMERIC(18,4), stop_loss NUMERIC(18,4), target_price NUMERIC(18,4), confidence NUMERIC(5,4), reason_codes JSONB NOT NULL DEFAULT '[]'::jsonb, source VARCHAR(40) NOT NULL DEFAULT 'RULES', status VARCHAR(32) NOT NULL DEFAULT 'CANDIDATE', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS paper_trade (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), symbol VARCHAR(20) NOT NULL, side VARCHAR(8) NOT NULL CHECK (side IN ('BUY','SELL')), quantity INTEGER NOT NULL CHECK (quantity > 0), entry_price NUMERIC(18,4) NOT NULL CHECK (entry_price > 0), stop_loss NUMERIC(18,4), target_price NUMERIC(18,4), estimated_cost NUMERIC(18,4) NOT NULL DEFAULT 0, risk_amount NUMERIC(18,4) NOT NULL, status VARCHAR(32) NOT NULL DEFAULT 'OPEN_PAPER', created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS idx_market_news_published_at ON market_news (published_at DESC);
CREATE INDEX IF NOT EXISTS idx_trade_signal_created_at ON trade_signal (created_at DESC);
CREATE INDEX IF NOT EXISTS idx_trade_signal_symbol_created_at ON trade_signal (symbol, created_at DESC);
CREATE INDEX IF NOT EXISTS idx_paper_trade_created_at ON paper_trade (created_at DESC);
